       navigate("/dashboard");
     },
   });

   const logoutMutation = useMutation({
     mutationFn: api.logout,
     onSettled: () => {
       clearTokens();
       queryClient.clear();
       navigate("/login");
     },
   });

   return {
-    isAuthenticated: !!user,
