import uuid

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session

from src.backend.core.deps import get_current_user, require_role
from src.backend.core.roles import Role
from src.backend.db.session import get_db
from src.backend.models.user import User
from src.backend.schemas.compliance import (
    ChecklistItemRead,
    ChecklistItemUpdate,
    ComplianceChecklistListResponse,
    ComplianceChecklistRead,
    ComplianceTemplateCreate,
    ComplianceTemplateListResponse,
    ComplianceTemplateRead,
    InstantiateChecklistRequest,
)
from src.backend.services import compliance_service as svc

router = APIRouter(prefix="/api", tags=["compliance"])


@router.get("/compliance-templates", response_model=ComplianceTemplateListResponse)
def list_templates(
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
    standard_code: str | None = None,
    is_active: bool | None = None,
) -> ComplianceTemplateListResponse:
    items, total, page, page_size = svc.list_templates_service(
        db, page=page, page_size=page_size, standard_code=standard_code, is_active=is_active
    )
    return ComplianceTemplateListResponse(
        items=items,
        total=total,
        page=page,
        page_size=page_size,
    )


@router.post(
    "/compliance-templates",
    response_model=ComplianceTemplateRead,
    status_code=status.HTTP_201_CREATED,
)
def create_template(
    body: ComplianceTemplateCreate,
    current_user: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> ComplianceTemplateRead:
    return svc.create_template_service(db, body, current_user.id)


@router.get("/compliance-templates/{template_id}", response_model=ComplianceTemplateRead)
def get_template(
    template_id: uuid.UUID,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> ComplianceTemplateRead:
    template = svc.get_template_service(db, template_id)
    if not template:
        raise HTTPException(status_code=404, detail="Template not found")
    return template


@router.get("/projects/{project_id}/compliance-checklists", response_model=ComplianceChecklistListResponse)
def list_project_checklists(
    project_id: uuid.UUID,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
) -> ComplianceChecklistListResponse:
    items, total, page, page_size = svc.list_project_checklists_service(
        db, project_id, page=page, page_size=page_size
    )
    return ComplianceChecklistListResponse(
        items=[ComplianceChecklistRead(**item) for item in items],
        total=total,
        page=page,
        page_size=page_size,
    )


@router.post(
    "/projects/{project_id}/compliance-checklists",
    response_model=ComplianceChecklistRead,
    status_code=status.HTTP_201_CREATED,
)
def instantiate_checklist(
    project_id: uuid.UUID,
    body: InstantiateChecklistRequest,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> ComplianceChecklistRead:
    result = svc.instantiate_checklist_service(db, project_id, body, current_user.id)
    if not result:
        raise HTTPException(status_code=404, detail="Template not found")
    return ComplianceChecklistRead(**result)


@router.get("/compliance-checklists/{checklist_id}", response_model=ComplianceChecklistRead)
def get_checklist(
    checklist_id: uuid.UUID,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> ComplianceChecklistRead:
    result = svc.get_checklist_service(db, checklist_id)
    if not result:
        raise HTTPException(status_code=404, detail="Checklist not found")
    return ComplianceChecklistRead(**result)


@router.patch(
    "/compliance-checklists/{checklist_id}/items/{item_id}",
    response_model=ComplianceChecklistRead,
)
def update_checklist_item(
    checklist_id: uuid.UUID,
    item_id: uuid.UUID,
    body: ChecklistItemUpdate,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> ComplianceChecklistRead:
    result = svc.update_checklist_item_service(db, checklist_id, item_id, body, current_user.id)
    if not result:
        raise HTTPException(status_code=404, detail="Checklist or item not found")
    return ComplianceChecklistRead(**result)


@router.delete("/compliance-checklists/{checklist_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_checklist(
    checklist_id: uuid.UUID,
    current_user: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> None:
    success = svc.delete_checklist_service(db, checklist_id, current_user.id)
    if not success:
        raise HTTPException(status_code=404, detail="Checklist not found")

